{
  "claims": [
    {
      "claim": "The query is the parent guanine acyclic nucleoside ganciclovir. Comparative evidence from the valganciclovir dataset reports ganciclovir oral bioavailability at about 6%, far below the 20% threshold, whereas the L-valine ester prodrug valganciclovir achieves about 60%; the query lacks the ester prodrug enhancement.",
      "evidence_role": "supportive",
      "molecule_ids": [
        "Molecule 11"
      ],
      "record_ids": [
        "Record 11-4"
      ]
    },
    {
      "claim": "Valganciclovir's high F values (43-60%) depend on PEPT1-mediated absorption of the prodrug and conversion to ganciclovir after absorption; those values do not transfer to ganciclovir itself, which is the query.",
      "evidence_role": "supportive",
      "molecule_ids": [
        "Molecule 11",
        "Molecule 28"
      ],
      "record_ids": [
        "Record 11-25",
        "Record 28-1"
      ]
    },
    {
      "claim": "Some related purine nucleosides display oral bioavailability above threshold (fludarabine 30-80%, cladribine 40-46%, roscovitine good, AT-527 at least 50%, theophylline 93.4%), but their structures and/or prodrug/transport mechanisms differ from ganciclovir and they do not establish a pass for the query.",
      "evidence_role": "contradictory",
      "molecule_ids": [
        "Molecule 6",
        "Molecule 8",
        "Molecule 9",
        "Molecule 3",
        "Molecule 5"
      ],
      "record_ids": [
        "Record 6-10",
        "Record 8-1",
        "Record 9-1",
        "Record 3-1",
        "Record 5-1"
      ]
    },
    {
      "claim": "Additional low-bioavailability examples, including didanosine (17-19% fed), saquinavir (4%), cefditoren (14% fasting), and selgantolimod (extremely poor), are consistent with high-polarity drugs failing the 20% oral bioavailability threshold, though their structural transfer is limited.",
      "evidence_role": "supportive",
      "molecule_ids": [
        "Molecule 2",
        "Molecule 4",
        "Molecule 7",
        "Molecule 10"
      ],
      "record_ids": [
        "Record 2-1",
        "Record 4-1",
        "Record 7-1",
        "Record 10-1"
      ]
    }
